const products = [
  { name: "Tecno Spark 20", price: 145000, category: "Phones" },
  { name: "Indomie Carton", price: 13500, category: "Groceries" },
  { name: "JBL Flip 6", price: 129000, category: "Electronics" },
  { name: "Peak Milk Tin", price: 16500, category: "Groceries" },
  { name: "Infinix Hot 40", price: 179000, category: "Phones" },
]
const total = (list) => list.reduce((sum, p) => sum + p.price, 0)
const sortByPrice = (list) => [...list].sort((a, b) => a.price - b.price)
const sortByName = (list) => [...list].sort((a, b) => a.name.localeCompare(b.name))
const categoryTotals = (list) => list.reduce((acc, p) => {
  acc[p.category] = (acc[p.category] ?? 0) + p.price
  return acc
}, {})
const topN = (list, n) => [...list].sort((a, b) => b.price - a.price).slice(0, n).map((p) => p.name)
